// Generated by Decentraland Studio. Do not edit: this copy is kept in sync with your editor version.
// The compact HUD set: what stays on screen while the game plays. A HUD is minimal and sits at the screen edges,
// leaving the centre (the avatar, what the player acts on) and the phone's touch buttons clear. Detail the player
// does not need every second goes in a window (./uiWindow), opened on demand.
//
// mountCompactHud(read) places the usual game HUD in the shared layout (./hudLayout) and returns its removal.
// read() runs every frame; leave a field out (or null) and its piece is not drawn:
//   mountCompactHud(() => ({ timer: secondsLeft, score: myScore, objective: 'Deliver the soup', status: holding }))
// - timer: seconds, as m:ss at the top centre; under `warnBelow` seconds (default 10) it turns red;
// - objective: one line under the timer, what to do now (short: about 30 characters fit on a phone);
// - score: the player's score in the right column, `scoreLabel` beside it (default 'Score');
// - status: one short line in the left column (what you hold, lives, round 2/3), tinted by `tone`.
// The pieces, to place yourself with addHudItem:
//   <HudChip label="Coins" value="12" icon={actionIcon('pick-up')} tone="good" id="hud-coins" />
//   <HudTimer seconds={42} />  <HudObjective text="Reach the tower" />  <HudStatus text="Holding: tomato" />
//   <HudIconButton icon={actionIcon('use')} label="Menu" onClick={openMenu} id="hud-menu" />
// Each has a fixed height from uiSizes('hud') (./uiComponents), so a whole compact HUD covers under 5% of a phone
// screen. HudIconButton is for rare actions (menu, mute, language): put it in the right column or the top corners,
// never under the right thumb, where the phone's own action buttons are. `id` becomes the uiTransform elementId of
// the text, so the editor's mobile check measures it.
import ReactEcs, { UiEntity } from '@dcl/sdk/react-ecs'
import { engine } from '@dcl/sdk/ecs'
import { isMobile } from '@dcl/sdk/platform'
import { sceneUiTheme } from './uiTheme'
import { ThemedEntity, UiText, uiSizes } from './uiComponents'
import { addHudItem, HUD_COLUMN_WIDTH } from './hudLayout'
import type { UiColor, UiTheme } from './pure/uiTheme'

export type HudTone = 'normal' | 'good' | 'warn' | 'danger'

function toneColor(theme: UiTheme, tone: HudTone | undefined): UiColor {
  if (tone === 'good') return theme.success
  if (tone === 'warn') return theme.accentText
  if (tone === 'danger') return theme.danger
  return theme.text
}

export function hudChipHeight(): number {
  const size = uiSizes('hud')
  return Math.round(size.text * 1.4) + 2 * size.pad
}

export function formatClock(seconds: number): string {
  const whole = Math.max(0, Math.ceil(seconds))
  return `${Math.floor(whole / 60)}:${String(whole % 60).padStart(2, '0')}`
}

export function HudChip(props: { value: string; label?: string; icon?: string; tone?: HudTone; width?: number; id?: string; theme?: UiTheme }) {
  const theme = props.theme ?? sceneUiTheme()
  const size = uiSizes('hud')
  const height = hudChipHeight()
  const iconSize = height - 2 * size.pad
  return <ThemedEntity uiTransform={{ width: props.width ?? 200, height, flexDirection: 'row', alignItems: 'center', padding: { left: size.pad * 1.5, right: size.pad * 1.5 },
    borderRadius: theme.radius, flexShrink: 0, pointerFilter: 'none' }} uiBackground={{ color: theme.panel }}>
    {props.icon !== undefined && <UiEntity uiTransform={{ width: iconSize, height: iconSize, flexShrink: 0, margin: { right: size.gap }, pointerFilter: 'none' }}
      uiBackground={{ texture: { src: props.icon }, textureMode: 'stretch', color: toneColor(theme, props.tone) }} />}
    {props.label !== undefined && <UiText value={props.label} color={theme.muted} size={size.small} height={iconSize} uiTransform={{ width: 'auto', flexGrow: 1 }} />}
    <UiText value={props.value} color={toneColor(theme, props.tone)} size={size.text} height={iconSize} mono
      align={props.label === undefined && props.icon === undefined ? 'middle-center' : 'middle-right'}
      uiTransform={{ width: 'auto', flexGrow: 1, ...(props.id === undefined ? {} : { elementId: props.id }) }} />
  </ThemedEntity>
}

export function HudTimer(props: { seconds: number; warnBelow?: number; width?: number; id?: string; theme?: UiTheme }) {
  const warn = props.seconds <= (props.warnBelow ?? 10)
  return <HudChip value={formatClock(props.seconds)} tone={warn ? 'danger' : 'normal'} width={props.width ?? 140} id={props.id ?? 'hud-timer'} theme={props.theme} />
}

export function HudObjective(props: { text: string; width?: number; id?: string; theme?: UiTheme }) {
  const theme = props.theme ?? sceneUiTheme()
  const size = uiSizes('hud')
  const height = Math.round(size.small * 1.5) + size.pad
  return <ThemedEntity uiTransform={{ width: props.width ?? HUD_COLUMN_WIDTH, height, padding: { left: size.pad, right: size.pad }, borderRadius: theme.radius,
    flexShrink: 0, pointerFilter: 'none' }} uiBackground={{ color: theme.tint }}>
    <UiText value={props.text} color={theme.text} size={size.small} height={height} align="middle-center" uiTransform={{ elementId: props.id ?? 'hud-objective' }} />
  </ThemedEntity>
}

export function HudStatus(props: { text: string; tone?: HudTone; width?: number; id?: string; theme?: UiTheme }) {
  const theme = props.theme ?? sceneUiTheme()
  const size = uiSizes('hud')
  const height = Math.round(size.small * 1.5) + size.pad
  return <ThemedEntity uiTransform={{ width: props.width ?? 260, height, padding: { left: size.pad * 1.5, right: size.pad }, borderRadius: theme.radius,
    flexShrink: 0, pointerFilter: 'none' }} uiBackground={{ color: theme.panel }}>
    <UiText value={props.text} color={toneColor(theme, props.tone)} size={size.small} height={height} uiTransform={{ elementId: props.id ?? 'hud-status' }} />
  </ThemedEntity>
}

export function HudIconButton(props: { icon: string; label: string; onClick(): void; id?: string; theme?: UiTheme }) {
  const theme = props.theme ?? sceneUiTheme()
  const size = uiSizes('hud')
  const phone = isMobile()
  const mark = Math.round(size.button * 0.55)
  return <ThemedEntity uiTransform={{ width: phone ? size.button : 'auto', height: size.button, flexDirection: 'row', alignItems: 'center', justifyContent: 'center',
    padding: phone ? 0 : { left: size.pad, right: size.pad * 1.5 }, borderRadius: theme.radius, flexShrink: 0, pointerFilter: 'block',
    ...(props.id === undefined ? {} : { elementId: props.id }) }} uiBackground={{ color: theme.surface }} onMouseDown={() => props.onClick()}>
    <UiEntity uiTransform={{ width: mark, height: mark, flexShrink: 0, pointerFilter: 'none' }} uiBackground={{ texture: { src: props.icon }, textureMode: 'stretch', color: theme.text }} />
    {!phone && <UiText value={props.label} color={theme.text} size={size.small} height={mark} uiTransform={{ width: 'auto', margin: { left: size.gap } }} />}
  </ThemedEntity>
}

export interface CompactHudState {
  timer?: number | null
  warnBelow?: number
  objective?: string | null
  score?: number | string | null
  scoreLabel?: string
  status?: string | null
  tone?: HudTone
}

const shown = <T,>(value: T | null | undefined): value is T => value !== undefined && value !== null && value !== ''

export function mountCompactHud(read: () => CompactHudState): () => void {
  let hud = read()
  const refresh = () => { hud = read() }
  engine.addSystem(refresh)
  const removals = [
    addHudItem('top', () => shown(hud.timer) ? <HudTimer seconds={hud.timer} warnBelow={hud.warnBelow} /> : null, { order: -50 }),
    addHudItem('top', () => shown(hud.objective) ? <HudObjective text={hud.objective} /> : null, { order: -40 }),
    addHudItem('right', () => shown(hud.score) ? <HudChip label={hud.scoreLabel ?? 'Score'} value={String(hud.score)} id="hud-score" /> : null, { order: -50 }),
    addHudItem('left', () => shown(hud.status) ? <HudStatus text={hud.status} tone={hud.tone} /> : null, { order: -50 })
  ]
  return () => {
    engine.removeSystem(refresh)
    for (const remove of removals) remove()
  }
}
